import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } = ctx.THREE;

  // Root object
  const root = new Group();

  // Geometry & material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply rotation & scale if provided (position handled by adapter)
  if (config.rotation) mesh.rotation.set(...config.rotation);
  if (config.scale) mesh.scale.set(...config.scale);

  // Load texture asynchronously (function stays sync)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Store timelines for cleanup
  const timelines = [];

  // Hover lift (rise‑in)
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(mesh.position, {
    y: mesh.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(hoverTL);

  // Click press‑down
  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(mesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  });
  timelines.push(pressTL);

  // Cinematic primitives (if any)
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    if (ctx.primitives[prim.name]) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // Event handlers
  root.userData.handlers = {
    hover: (enter) => {
      if (enter) hoverTL.play();
      else hoverTL.reverse();
    },
    click: () => {
      pressTL.restart();
      ctx.emit('navigate', { to: 'hub-pricing' });
    },
  };

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h.cleanup && h.cleanup());
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return root;
}
